namespace Mcs.Compiler;

/// <summary>
/// C# stub declarations for MC#'s built-in APIs.
/// Roslyn type-checks against these declarations, and the code generator reads
/// their attributes ([Intrinsic], [Nbt], [McAttribute], [McId], [State]) to decide which commands to emit.
/// The method bodies never run. EntityType and the per-block classes are generated by PreludeGen.
/// </summary>
public static class Prelude
{
    public const string GlobalUsings = """
        global using MCS;
        global using static MCS.Builtins;
        global using Milli = System.Single;
        global using Q16 = System.Double;
        """;

    public const string Source = """
        namespace MCS
        {
            [System.AttributeUsage(System.AttributeTargets.All)]
            public sealed class IntrinsicAttribute : System.Attribute { public IntrinsicAttribute(string name) { } }

            /// Entity NBT path mapping. type: byte|short|int|long|float|double|string|int[]
            [System.AttributeUsage(System.AttributeTargets.Property)]
            public sealed class NbtAttribute : System.Attribute { public NbtAttribute(string path, string type) { } }

            /// Entity attribute mapping (written without the "generic." prefix; the compiler adds it per version).
            [System.AttributeUsage(System.AttributeTargets.Property)]
            public sealed class McAttributeAttribute : System.Attribute { public McAttributeAttribute(string id) { } }

            /// Minecraft ID (block / entity type / state value).
            [System.AttributeUsage(System.AttributeTargets.All)]
            public sealed class McIdAttribute : System.Attribute { public McIdAttribute(string id) { } }

            /// Block state property: state name and allowed values.
            [System.AttributeUsage(System.AttributeTargets.Property)]
            public sealed class StateAttribute : System.Attribute { public StateAttribute(string name, string values) { } }

            /// Marks a class as an entity class: instances are entities of this type (+ tag).
            [System.AttributeUsage(System.AttributeTargets.Class)]
            public sealed class EntityAttribute : System.Attribute { public EntityAttribute(string type, string tag = null) { } }

            /// The member exists from this data pack format / version on (older targets are a compile error).
            [System.AttributeUsage(System.AttributeTargets.All)]
            public sealed class SinceAttribute : System.Attribute { public SinceAttribute(int format, string version) { } }

            /// Per-entity scoreboard field. Default objective: <namespace>.<field_name>
            [System.AttributeUsage(System.AttributeTargets.Field)]
            public sealed class ScoreAttribute : System.Attribute
            {
                public ScoreAttribute(string objective = null) { }
                public string Display { get; set; }
                public string Color { get; set; }
                public string Criteria { get; set; }
            }

            /// The method body is inlined at each call site; constant arguments stay compile-time constants.
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class InlineAttribute : System.Attribute { }

            /// Runs every time the datapack loads (#minecraft:load).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class LoadAttribute : System.Attribute { }

            /// Runs every tick (#minecraft:tick).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class TickAttribute : System.Attribute { }

            // ---- Player events. The method runs as the player, at the player (@s). Parameters (all optional):
            //      a Player (that player) and, for counter events, an int (how much the counter went up).

            /// A player joins the world (every login, including the first).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnJoinAttribute : System.Attribute { }

            /// A player joins for the first time (also players online when the pack is first installed).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnFirstJoinAttribute : System.Attribute { }

            /// A player died (runs at the death position, while the player is on the death screen).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnDeathAttribute : System.Attribute { }

            /// A player respawned after dying.
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnRespawnAttribute : System.Attribute { }

            /// A player killed something (mob or player). int parameter: number of kills.
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnKillAttribute : System.Attribute { }

            /// A player used an item. Right-click detection works for carrot_on_a_stick and warped_fungus_on_a_stick;
            /// other items count when they are actually used (eaten, thrown, placed, …).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnRightClickAttribute : System.Attribute { public OnRightClickAttribute(string item = "carrot_on_a_stick") { } }

            /// A player ran /trigger <objective> (no operator permission needed). int parameter: the value (1 for a plain /trigger).
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnTriggerAttribute : System.Attribute { public OnTriggerAttribute(string objective) { } }

            /// A player right-clicked while holding this item object (a static Item field):
            /// [OnRightClickObject(nameof(wand))]. The item must be carrot_on_a_stick or warped_fungus_on_a_stick.
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnRightClickObjectAttribute : System.Attribute { public OnRightClickObjectAttribute(string field) { } }

            /// A statistic of a player went up, e.g. "minecraft.custom:minecraft.jump" or "minecraft.mined:minecraft.stone".
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class OnStatAttribute : System.Attribute { public OnStatAttribute(string criterion) { } }

            /// `/` and `%` in this method or class use Minecraft's own scoreboard division: one command, rounds toward
            /// −∞, and the remainder takes the divisor's sign (-7 / 2 = -4, -7 % 2 = 1). Faster than C# division.
            [System.AttributeUsage(System.AttributeTargets.Method | System.AttributeTargets.Class)]
            public sealed class MinecraftDivisionAttribute : System.Attribute { }

            /// `/` and `%` in this method or class use C# division even when the project uses "division": "minecraft".
            [System.AttributeUsage(System.AttributeTargets.Method | System.AttributeTargets.Class)]
            public sealed class CSharpDivisionAttribute : System.Attribute { }

            /// A function of another datapack: [External("other:path/func")] static extern void F();
            /// Parameters become macro arguments ($(name), 1.20.2+); an int/bool result is the function's /return value.
            /// Function tags work too: [External("#other:hooks")].
            [System.AttributeUsage(System.AttributeTargets.Method)]
            public sealed class ExternalAttribute : System.Attribute { public ExternalAttribute(string function) { } }

            /// A static class whose extern methods are methods of another MC# datapack (its namespace, and the class
            /// the methods are declared in there, if any). Arguments and results use that pack's scores.
            [System.AttributeUsage(System.AttributeTargets.Class)]
            public sealed class McsPackAttribute : System.Attribute { public McsPackAttribute(string ns, string className = null) { } }

            /// A string that exists at run time, stored in NBT storage. Comparing, Length, Substring work on every
            /// version; joining values (+, $"...") and runtime indexes need function macros (1.20.2+).
            public sealed class NString
            {
                public static implicit operator NString(string s) => null;
                [Intrinsic("nstr.concat")] public static NString operator +(NString a, NString b) => null;
                [Intrinsic("nstr.concat")] public static NString operator +(NString a, object b) => null;
                [Intrinsic("nstr.concat")] public static NString operator +(object a, NString b) => null;
                [Intrinsic("nstr.eq")] public static bool operator ==(NString a, NString b) => false;
                [Intrinsic("nstr.ne")] public static bool operator !=(NString a, NString b) => false;
                public override bool Equals(object o) => false;
                public override int GetHashCode() => 0;
                [Intrinsic("nstr.length")] public int Length => 0;
                [Intrinsic("nstr.isempty")] public bool IsEmpty => false;
                /// One character (as an NString).
                [Intrinsic("nstr.char")] public NString this[int index] => null;
                [Intrinsic("nstr.sub")] public NString Substring(int start) => null;
                [Intrinsic("nstr.sub")] public NString Substring(int start, int length) => null;
                [Intrinsic("nstr.starts")] public bool StartsWith(NString prefix) => false;
                [Intrinsic("nstr.ends")] public bool EndsWith(NString suffix) => false;
                /// Position of the first occurrence, or -1 (1.20.2+).
                [Intrinsic("nstr.indexof")] public int IndexOf(NString value) => 0;
                [Intrinsic("nstr.contains")] public bool Contains(NString value) => false;
                /// Parses the text as an integer (0 if it is not a number; 1.20.2+).
                [Intrinsic("nstr.toint")] public int ToInt() => 0;
                /// The text of any value: NString.From(score) (1.20.2+ for runtime values).
                [Intrinsic("nstr.from")] public static NString From(object value) => null;
            }

            /// An array whose length can change at run time, stored in NBT storage. T: int, bool, Milli, Q16, NString.
            /// Constant indexes, Add, Length and foreach work on every version; runtime indexes need 1.20.2+ (macros).
            public sealed class NArray<T> : System.Collections.Generic.IEnumerable<T>
            {
                [Intrinsic("narr.new")] public NArray() { }
                /// `length` elements with the default value (0 / false / "").
                [Intrinsic("narr.new")] public NArray(int length) { }
                [Intrinsic("narr.index")] public T this[int index] { get => default; set { } }
                [Intrinsic("narr.length")] public int Length => 0;
                [Intrinsic("narr.length")] public int Count => 0;
                [Intrinsic("narr.add")] public void Add(T value) { }
                [Intrinsic("narr.insert")] public void Insert(int index, T value) { }
                [Intrinsic("narr.removeat")] public void RemoveAt(int index) { }
                /// Removes the last element and returns it.
                [Intrinsic("narr.pop")] public T Pop() => default;
                [Intrinsic("narr.clear")] public void Clear() { }
                public System.Collections.Generic.IEnumerator<T> GetEnumerator() => null;
                System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => null;
            }

            /// Base class of scoreboard classes: `public class test : dummy {}` — every static int/bool field
            /// is a score holder (the field name) in the class's objective (criteria dummy, created on load).
            /// Using test.anything declares the field automatically.
            public abstract class dummy { }

            /// A compile-time position (an execute context + coordinates).
            public struct Position
            {
                [Intrinsic("pos.new")] public Position(double x, double y, double z) { }
                [Intrinsic("pos.here")] public static Position Here => default;
                [Intrinsic("pos.offset")] public Position Offset(double dx, double dy, double dz) => default;
                /// The same position in another dimension (execute in …).
                [Intrinsic("pos.in")] public Position In(WorldLib.Dimension dimension) => default;
            }

            /// Base class of entity classes ([Entity("minecraft:marker", "my.tag")] class Province : EntityObject).
            public abstract class EntityObject
            {
                [Intrinsic("ent.addtag")] public void AddTag(string tag) { }
                [Intrinsic("ent.removetag")] public void RemoveTag(string tag) { }
                [Intrinsic("ent.hastag")] public bool HasTag(string tag) => false;
                [Intrinsic("ent.kill")] public void Kill() { }
                [Intrinsic("ent.merge")] public void Merge(string snbt) { }
                [Intrinsic("ent.pos")] public Position Position => default;
                [Intrinsic("ent.tp")] public void Teleport(Position pos) { }
                [Intrinsic("ent.run")] public void Run(System.Action action) { }

                // ---- interactions (EntityLib also has these for Entity objects)
                /// Deals damage (1.19.4+ /damage). attacker: an Entity or entity reference.
                [Intrinsic("ex.damage")] public void Damage(float amount, string type = "generic", object attacker = null) { }
                /// Rides the vehicle (an Entity or entity reference).
                [Intrinsic("ex.ride")] public void Ride(object vehicle) { }
                [Intrinsic("ex.dismount")] public void Dismount() { }
                [Intrinsic("ex.tpto")] public void TeleportTo(object target) { }
                [Intrinsic("ex.lookat")] public void LookAt(Position pos) { }
                [Intrinsic("ex.lookat")] public void LookAt(object target) { }
                [Intrinsic("ex.motion")] public void SetMotion(double x, double y, double z) { }
                /// Whether `other` is within `distance` blocks.
                [Intrinsic("ex.near")] public bool IsNear(object other, double distance) => false;
                [Intrinsic("ex.isin")] public bool IsIn(WorldLib.Dimension dimension) => false;
            }

            /// Entity queries. Selector filters use selector syntax, e.g. "tag=a,scores={x=1..}".
            public static class Entities
            {
                [Intrinsic("ents.all")] public static System.Collections.Generic.IEnumerable<T> All<T>(string filter = "", bool at = false) where T : EntityObject => null;
                [Intrinsic("ents.spawn")] public static T Spawn<T>(Position pos, string nbt = "") where T : EntityObject => null;
                [Intrinsic("ents.nearest")] public static T Nearest<T>(Position pos, double maxDistance = -1, string filter = "") where T : EntityObject => null;
                [Intrinsic("ents.random")] public static T Random<T>(string filter = "") where T : EntityObject => null;
                [Intrinsic("ents.first")] public static T First<T>(string filter = "") where T : EntityObject => null;
                [Intrinsic("ents.count")] public static int Count<T>(string filter = "") where T : EntityObject => 0;
                [Intrinsic("ents.any")] public static bool Any<T>(string filter = "") where T : EntityObject => false;
                [Intrinsic("ents.self")] public static T Self<T>() where T : EntityObject => null;
                [Intrinsic("ents.uuid")] public static T Uuid<T>(string uuid) where T : EntityObject => null;
            }

            /// Compile-time loops: foreach (int i in Unroll.Range(0, 3)) is expanded at compile time.
            public static class Unroll
            {
                [Intrinsic("unroll.range")] public static int[] Range(int from, int toExclusive) => null;
            }

            /// Execute contexts.
            public static class Exec
            {
                [Intrinsic("exec.run")] public static void Run(string subcommands, System.Action action) { }
                [Intrinsic("exec.at")] public static void At(Position pos, System.Action action) { }
            }

            /// The MC# runtime mod (mcs.jar, Minecraft 26.1+). See "runtime" in mcs.json.
            public static class Runtime
            {
                /// Is the runtime mod installed on this server? (always false below 26.1 or with "runtime": "off")
                [Intrinsic("rt.available")] public static bool IsAvailable => false;
                /// Runs a command with the mod's permission level 4 (op, ban, whitelist, stop …). Needs
                /// "runtime": "required". The command may contain runtime values ($"whitelist add {name}").
                [Intrinsic("rt.sudo")] public static void Sudo(string command) { }
            }

            /// A fluent /execute: Execute.AsPlayerObject(p).At(p).IfBlock("stone", pos).Run(() => { ... }).
            /// Write the whole chain in one statement ending with .Run(...). Targets are an Entity, an entity
            /// reference (Player.All, an entity class) or a selector string.
            public static class Execute
            {
                /// as <target>: runs for each target as @s.
                [Intrinsic("xc.as")] public static ExecuteChain As(object target) => default;
                /// as <players>: runs for each player as @s.
                [Intrinsic("xc.as")] public static ExecuteChain AsPlayerObject(PlayerLib.Player players) => default;
                /// at <target>: the position, rotation and dimension of each target.
                [Intrinsic("xc.at")] public static ExecuteChain At(object target) => default;
                /// The position (and its dimension).
                [Intrinsic("xc.pos")] public static ExecuteChain At(Position pos) => default;
                [Intrinsic("xc.pos")] public static ExecuteChain Positioned(Position pos) => default;
                [Intrinsic("xc.in")] public static ExecuteChain In(WorldLib.Dimension dimension) => default;
                [Intrinsic("xc.facing")] public static ExecuteChain Facing(Position pos) => default;
                [Intrinsic("xc.facingent")] public static ExecuteChain Facing(object target) => default;
                [Intrinsic("xc.rotated")] public static ExecuteChain Rotated(float yaw, float pitch) => default;
                [Intrinsic("xc.rotatedas")] public static ExecuteChain RotatedAs(object target) => default;
                [Intrinsic("xc.eyes")] public static ExecuteChain AnchoredEyes() => default;
                /// align <axes> ("xyz", "xz", ...).
                [Intrinsic("xc.align")] public static ExecuteChain Align(string axes) => default;
                [Intrinsic("xc.ifblock")] public static ExecuteChain IfBlock(string id, Position pos) => default;
                [Intrinsic("xc.ifblockobj")] public static ExecuteChain IfBlockObject(BlockLib.Block block, Position pos) => default;
                [Intrinsic("xc.unlessblock")] public static ExecuteChain UnlessBlock(string id, Position pos) => default;
                [Intrinsic("xc.unlessblockobj")] public static ExecuteChain UnlessBlockObject(BlockLib.Block block, Position pos) => default;
                /// if entity <target>: continues if the target exists.
                [Intrinsic("xc.ifentity")] public static ExecuteChain IfEntity(object target) => default;
                [Intrinsic("xc.unlessentity")] public static ExecuteChain UnlessEntity(object target) => default;
                /// Continues if the condition is true (checked at this point of the chain, e.g. once per As target).
                [Intrinsic("xc.if")] public static ExecuteChain If(bool condition) => default;
                [Intrinsic("xc.unless")] public static ExecuteChain Unless(bool condition) => default;
                /// Raw execute subcommands ("anchored eyes positioned ^ ^ ^1").
                [Intrinsic("xc.raw")] public static ExecuteChain Sub(string subcommands) => default;
            }

            /// The rest of an Execute chain (see Execute). End it with .Run(...).
            public struct ExecuteChain
            {
                [Intrinsic("xc.as")] public ExecuteChain As(object target) => default;
                [Intrinsic("xc.as")] public ExecuteChain AsPlayerObject(PlayerLib.Player players) => default;
                [Intrinsic("xc.at")] public ExecuteChain At(object target) => default;
                [Intrinsic("xc.pos")] public ExecuteChain At(Position pos) => default;
                [Intrinsic("xc.pos")] public ExecuteChain Positioned(Position pos) => default;
                [Intrinsic("xc.in")] public ExecuteChain In(WorldLib.Dimension dimension) => default;
                [Intrinsic("xc.facing")] public ExecuteChain Facing(Position pos) => default;
                [Intrinsic("xc.facingent")] public ExecuteChain Facing(object target) => default;
                [Intrinsic("xc.rotated")] public ExecuteChain Rotated(float yaw, float pitch) => default;
                [Intrinsic("xc.rotatedas")] public ExecuteChain RotatedAs(object target) => default;
                [Intrinsic("xc.eyes")] public ExecuteChain AnchoredEyes() => default;
                [Intrinsic("xc.align")] public ExecuteChain Align(string axes) => default;
                [Intrinsic("xc.ifblock")] public ExecuteChain IfBlock(string id, Position pos) => default;
                [Intrinsic("xc.ifblockobj")] public ExecuteChain IfBlockObject(BlockLib.Block block, Position pos) => default;
                [Intrinsic("xc.unlessblock")] public ExecuteChain UnlessBlock(string id, Position pos) => default;
                [Intrinsic("xc.unlessblockobj")] public ExecuteChain UnlessBlockObject(BlockLib.Block block, Position pos) => default;
                [Intrinsic("xc.ifentity")] public ExecuteChain IfEntity(object target) => default;
                [Intrinsic("xc.unlessentity")] public ExecuteChain UnlessEntity(object target) => default;
                [Intrinsic("xc.if")] public ExecuteChain If(bool condition) => default;
                [Intrinsic("xc.unless")] public ExecuteChain Unless(bool condition) => default;
                [Intrinsic("xc.raw")] public ExecuteChain Sub(string subcommands) => default;
                /// Runs the lambda (or a parameterless static method) in the chain's context.
                [Intrinsic("xc.run")] public void Run(System.Action action) { }
            }

            /// Global functions: call them without a class name (Wait(20), GetWorldSpawn()).
            public static class Builtins
            {
                [Intrinsic("asm")] public static void __asm(string commands) { }
                [Intrinsic("asmf")] public static void __asmf(string command) { }
                [Intrinsic("worldspawn")] public static Position GetWorldSpawn() => default;
                [Intrinsic("setworldspawn")] public static void SetWorldSpawn(Position pos) { }
                [Intrinsic("spawn.id")] public static void SpawnEntity(string id, Position pos, int count = 1) { }
                /// Pauses this method for one tick (or `ticks`): the rest of the method runs later via /schedule.
                /// The caller does not wait — it continues right away.
                [Intrinsic("wait")] public static void Wait(int ticks = 1) { }
            }
        }

        namespace EntityLib
        {
            public class Entity
            {
                [MCS.Intrinsic("entity.new")] public Entity(EntityType type) { }
                protected Entity() { }

                [MCS.Nbt("Health", "float")] public float Health { get; set; }
                [MCS.McAttribute("max_health")] public float maxHealth { get; set; }
                [MCS.McAttribute("max_health")] public float MaxHealth { get; set; }
                [MCS.McAttribute("movement_speed")] public float MovementSpeed { get; set; }
                [MCS.McAttribute("attack_damage")] public float AttackDamage { get; set; }
                [MCS.McAttribute("armor")] public float Armor { get; set; }
                [MCS.Nbt("Fire", "short")] public int Fire { get; set; }
                [MCS.Nbt("Air", "short")] public int Air { get; set; }
                [MCS.Nbt("NoAI", "byte")] public bool NoAI { get; set; }
                [MCS.Nbt("Silent", "byte")] public bool Silent { get; set; }
                [MCS.Nbt("Glowing", "byte")] public bool Glowing { get; set; }
                [MCS.Nbt("Invulnerable", "byte")] public bool Invulnerable { get; set; }
                [MCS.Nbt("NoGravity", "byte")] public bool NoGravity { get; set; }
                [MCS.Nbt("PersistenceRequired", "byte")] public bool PersistenceRequired { get; set; }
                [MCS.Nbt("UUID", "int[]")] public int[] uuid => default!;
                [MCS.Nbt("UUID", "int[]")] public int[] UUID => default!;

                [MCS.Intrinsic("entity.pos")] public MCS.Position Position => default;
                [MCS.Intrinsic("entity.kill")] public void Kill() { }
                [MCS.Intrinsic("entity.tp")] public void Teleport(MCS.Position pos) { }
                /// A new, unspawned entity object of the same type with the same pre-spawn properties.
                [MCS.Intrinsic("obj.clone")] public Entity Clone() => null;
                /// Discards this object: it cannot be used any more.
                [MCS.Intrinsic("obj.dispose")] public void Dispose() { }

                // ---- interactions
                [MCS.Intrinsic("ex.addtag")] public void AddTag(string tag) { }
                [MCS.Intrinsic("ex.removetag")] public void RemoveTag(string tag) { }
                [MCS.Intrinsic("ex.hastag")] public bool HasTag(string tag) => false;
                /// Deals damage (/damage). attacker: an Entity or entity reference (e.g. Player.Self).
                [MCS.Intrinsic("ex.damage")] public void Damage(float amount, string type = "generic", object attacker = null) { }
                [MCS.Intrinsic("ex.effect")] public void Effect(string effect, int seconds, int amplifier = 0, bool hideParticles = false) { }
                [MCS.Intrinsic("ex.cleareffects")] public void ClearEffects() { }
                /// Rides the vehicle (an Entity or entity reference).
                [MCS.Intrinsic("ex.ride")] public void Ride(object vehicle) { }
                [MCS.Intrinsic("ex.dismount")] public void Dismount() { }
                [MCS.Intrinsic("ex.tpto")] public void TeleportTo(object target) { }
                [MCS.Intrinsic("ex.lookat")] public void LookAt(MCS.Position pos) { }
                [MCS.Intrinsic("ex.lookat")] public void LookAt(object target) { }
                [MCS.Intrinsic("ex.motion")] public void SetMotion(double x, double y, double z) { }
                [MCS.Intrinsic("ex.near")] public bool IsNear(object other, double distance) => false;
                [MCS.Intrinsic("ex.isin")] public bool IsIn(WorldLib.Dimension dimension) => false;
                [MCS.Intrinsic("ex.exists")] public bool Exists => false;
            }

            /// An interaction entity (an invisible hitbox that detects clicks; 1.19.4+).
            public sealed class Interaction : Entity
            {
                [MCS.Intrinsic("display.new")] public Interaction() { }
                [MCS.Nbt("width", "float")] public float Width { get; set; }
                [MCS.Nbt("height", "float")] public float Height { get; set; }
                /// Swing the player's arm when clicked.
                [MCS.Nbt("response", "byte")] public bool Response { get; set; }
                /// Was it right-clicked since the last call? (clears the click)
                [MCS.Intrinsic("interaction.clicked")] public bool Clicked() => false;
                /// Was it left-clicked (attacked) since the last call? (clears the attack)
                [MCS.Intrinsic("interaction.attacked")] public bool Attacked() => false;
                /// The player who right-clicked it last.
                [MCS.Intrinsic("interaction.clicker")] public PlayerLib.Player Clicker => null;
                /// The player who attacked it last.
                [MCS.Intrinsic("interaction.attacker")] public PlayerLib.Player Attacker => null;
                [MCS.Intrinsic("obj.clone")] public new Interaction Clone() => null;
            }
        }

        namespace WorldLib
        {
            public enum Weather { Clear, Rain, Thunder }
